    shortlisted: { bg: '#F3E8FF', color: '#6B21A8', label: 'Shortlisted' },
    hired: { bg: '#D1FAE5', color: '#065F46', label: 'Hired' },
    rejected: { bg: '#FEE2E2', color: '#991B1B', label: 'Not Selected' }
