                  Assign Staff
                </button>
              </form>
            </div>

            <div style={card}>
              <h3 style={{ fontSize: '16px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '16px' }}>
