                    <div key={app._id} style={{ background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '12px', border: `1px solid ${darkMode ? '#334155' : '#E2E8F0'}`, overflow: 'hidden' }}>
                      <button onClick={() => setExpandedAppId(isExpanded ? null : app._id)}
